<?php
namespace App\Http\Controllers\Crm;
use App\Http\Controllers\Controller;use App\Models\Reminder;use Illuminate\Http\Request;
class ReminderController extends Controller {public function index(Request $r){$u=$r->user();$reminders=Reminder::with(['customer.contacts','purchase.items'])->where('status','pending')->whereDate('due_date','<=',today())->when(!$u->isCeo(),fn($q)=>$q->whereHas('purchase',fn($p)=>$p->where('branch_id',$u->branch_id)))->orderBy('due_date')->paginate(30);return view('crm.reminders.index',compact('reminders'));}public function updateStatus(Request $r,Reminder $reminder){abort_unless($r->user()->isCeo()||$reminder->purchase()->where('branch_id',$r->user()->branch_id)->exists(),403);$d=$r->validate(['status'=>'required|in:terkirim,dibalas,tidak_direspon','channel'=>'nullable|in:wa_manual,telpon,email,lainnya','note'=>'nullable|string|max:500']);$reminder->update([...$d,'handled_by'=>$r->user()->id,'handled_at'=>now()]);return back()->with('ok','Status reminder diperbarui.');}}
